            Describe.Lean(DescribeId.Create("native-suffix-entry"), DeclarationHandle.Create("D5/S3/Arith/FibonacciAtomic/NativeContinuation/Acquisition/NativeSuffixAcquisition.entry"), H("Reading a seam count"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For every r : Row and s : Bool, entry r s is r.2 when s is true and r.1 when s is false."))), DescribeRole.Definition),
