            Describe.Lean(DescribeId.Create("native-suffix-counts"), DeclarationHandle.Create("D5/S3/Arith/FibonacciAtomic/NativeContinuation/Acquisition/NativeSuffixAcquisition.counts"), H("Current row"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For every B and as, counts B as is the head of table B as. The terminal row is the default, although the table is always nonempty."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("native-suffix-completions"), DeclarationHandle.Create("D5/S3/Arith/FibonacciAtomic/NativeContinuation/Acquisition/NativeSuffixAcquisition.completions"), H("Distinct successful words"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For every B, as and seam s, completions B as s is a finite set of original Window lists. The empty word occurs precisely when s is permitted by B. Otherwise each guarded allowed letter is prefixed to every completion from its actual successor. This finite set specifies cardinality and is not enumerated by table or reconstruct."))), DescribeRole.Definition),
