            Describe.Lean(DescribeId.Create("native-suffix-modes"), DeclarationHandle.Create("D5/S3/Arith/FibonacciAtomic/NativeContinuation/Acquisition/NativeSuffixAcquisition.modes"), H("Fixed reconstruction order"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The original letters are ordered zero, low, middle, high, ends. Window-internal printed bits retain their original low, middle, high order. The window list itself is read high to low."))), DescribeRole.Definition),
