            Describe.Lean(DescribeId.Create("native-suffix-acquire"), DeclarationHandle.Create("D5/S3/Arith/FibonacciAtomic/NativeContinuation/Acquisition/NativeSuffixAcquisition.acquire"), H("Table and word together"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For every B, as and s, acquire B as s computes table B as once and supplies that table to reconstruct. Its first component is the complete row list and its second component is an optional original word."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("native-suffix-acquisition"), DeclarationHandle.Create("D5/S3/Arith/FibonacciAtomic/NativeContinuation/Acquisition/NativeSuffixAcquisition.native_suffix_acquisition"), H("All suffix counts and successful native reconstruction"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("theorem native_suffix_acquisition (L : \u2115) (A : Fin L \u2192 Finset Window)     (B : Finset Bool) :     let as := List.ofFn A     (table B as).length = L + 1 \u2227     (\u2200 (t : Fin (L + 1)) (s : Bool),       (table B as)[t.val]? = some (counts B (as.drop t.val)) \u2227       entry (counts B (as.drop t.val)) s = (completions B (as.drop t.val) s).card \u2227       entry (counts B (as.drop t.val)) s \u2264 5 ^ (L - t.val) \u2227       \u2200 (c : \u2115 \u00d7 \u2115) (w : List Window),         w \u2208 completions B (as.drop t.val) s \u2194           Allowed (as.drop t.val) w \u2227 \u2203 u \u2208 B, \u2203 d : \u2115 \u00d7 \u2115, NativeHistory s c w u d) \u2227     (\u2200 s : Bool,       ((acquire B as s).2 = none \u2194 entry (counts B as) s = 0) \u2227       (entry (counts B as) s = 0 \u2194         \u00ac \u2203 (w : List Window) (u : Bool) (d : \u2115 \u00d7 \u2115),           Allowed as w \u2227 u \u2208 B \u2227 NativeHistory s (0, 0) w u d) \u2227       (0 < entry (counts B as) s \u2192         \u2203 (w : List Window) (u : Bool) (d : \u2115 \u00d7 \u2115),           (acquire B as s).2 = some w \u2227 w.length = L \u2227 Allowed as w \u2227 u \u2208 B \u2227           NativeHistory s (0, 0) w u d \u2227           (rawMachine 0).toDFA.evalFrom (some (s, residue 0 (0, 0))) w =             some (u, residue 0 d)))")), Paragraph(Text("Disjointness follows from the first original letter, rather than merely the successor seam. Induction computes the whole row list. A vanished row entry is equivalent to the absence of a successful restricted native word; a positive entry makes the fixed scan choose a positive child at every remaining step. NativeHistory supplies the same actual integer execution through native_execution, with no execution or representation premise."))), DescribeRole.Theorem)),
        [DocumentEdge.Dependency.Create(GidRef.Create("D5/S3/Arith/FibonacciAtomic/NativeContinuation/NullReplyFiber"))]));
